from heapq import heappop, heappush

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    heap = [(grid[0][0], 0, 0, [grid[0][0]])]
    visited = set()

    while heap:
        val, x, y, path = heappop(heap)
        if (x, y) in visited or len(path) > k:
            continue
        if len(path) == k:
            return path
        visited.add((x, y))
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                heappush(heap, (val + grid[nx][ny], nx, ny, path + [grid[nx][ny]]))

    return []

